local function C_b()
local script = G2L["b"];
	local player = game.Players.LocalPlayer
	local character = player.Character or player.CharacterAdded:Wait()
	local hrp = character:WaitForChild("HumanoidRootPart")

	script.Parent.MouseButton1Click:Connect(function() 
		hrp.CFrame = hrp.CFrame * CFrame.Angles(0, math.rad(-50), 0)
		task.wait(0.1)
		hrp.CFrame = hrp.CFrame * CFrame.Angles(0, math.rad(70), 0)
		task.wait(1.5)
	end)


end;
task.spawn(C_b);
-- StarterGui.WallHopScript.Frame.LoopFlickButton.LocalScript
local function C_f()
local script = G2L["f"];
	local player = game.Players.LocalPlayer
	local character = player.Character or player.CharacterAdded:Wait()
	local hrp = character:WaitForChild("HumanoidRootPart")
	local rotating = false

	local function getRotationInterval()
	    local textBox = script.Parent.Parent:FindFirstChild("Seconds") -- Assuming TextBox is a sibling of the button
	    if textBox then
	        local seconds = tonumber(textBox.Text)
	        if seconds and seconds > 0 then
	            return seconds
	        end
	    end
	    return 1 -- Default to 1 second if no valid input
	end

	script.Parent.MouseButton1Click:Connect(function() 
	    rotating = not rotating
	    if rotating then
	        script.Parent.Text = "Stop Flicking"
	        while rotating do
	            hrp.CFrame = hrp.CFrame * CFrame.Angles(0, math.rad(-60), 0)
	            task.wait(getRotationInterval())
	            hrp.CFrame = hrp.CFrame * CFrame.Angles(0, math.rad(60), 0)
	            task.wait(getRotationInterval())
	        end
	    else
	        script.Parent.Text = "Loop Flick"
	    end
	end)


end;
task.spawn(C_f);
